    for (let k = m; k >= 1; k--) { const ph = k / m * HALF; pre.push({ p: a.p.clone().addScaledVector(a.T, -r * Math.sin(ph)), N: a.N, B: a.B, T: a.T, r: k === m ? 0 : r * Math.cos(ph) }); }
