    const n = s.bays, bh = s.bayHeight, Wt = s.width, D = s.depth;
    const cw = 0.3, cx = Wt / 2 - cw / 2, xi = cx - cw / 2, foot = 0.05, y0 = foot + 0.36, Htot = y0 + n * bh + 0.36;
    const ny = k => y0 + k * bh;
    const frame = new Geo(), house = new Geo(), conn = new Geo(), dark = new Geo(), bolts = new Geo(), base = new Geo();
    const faces = (x, y, zFace, spots, d) => {            // bolts on the front and back faces at depth ±zFace
      if (!hi) return;
      boltsAt(bolts, T(x, y, zFace), spots, d);
      boltsAt(bolts, X(T(x, y, -zFace), RY(Math.PI)), spots.map(p => [-p[0], p[1]]), d);
    };
